support_table_dir <- file.path("Output_tables_2025", "translocation_processing_support")
support_figure_dir <- file.path("Output_figures_2025", "translocation_processing_support")
dir.create(support_table_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(support_figure_dir, recursive = TRUE, showWarnings = FALSE)

support_path <- function(filename) file.path(support_table_dir, filename)

write_support_rds <- function(x, filename) {
  path <- support_path(filename)
  saveRDS(x, file = path)
  message("Support RDS written: ", path)
  invisible(path)
}

support_png <- function(filename) file.path(support_figure_dir, filename)

first_existing <- function(candidates, label) {
  hit <- candidates[file.exists(candidates)][1]
  if (is.na(hit)) {
    stop(
      "Could not find ", label, ". Checked:\n  ",
      paste(candidates, collapse = "\n  "),
      call. = FALSE
    )
  }
  hit
}


