# 4. write BEDs
outdir_bed <- "IGV_screenshotter/Bed_files_translocations_cytoband"
if (!dir.exists(outdir_bed)) dir.create(outdir_bed, recursive = TRUE)

write_bed <- function(df, bam_name) {
  bed <- df %>%
    mutate(
      Chromosome = if_else(str_starts(Chromosome,"chr"), Chromosome, paste0("chr",Chromosome)),
      Start      = Start,
      End        = End
    ) %>%
    select(Chromosome, Start, End, Name)
  # write into the outdir:
  write_tsv(bed,
            file.path(outdir_bed, paste0(bam_name, ".bed")),
            col_names = FALSE)
}
  

screenshotter_df %>%
  group_by(Bam) %>%
  group_walk(~ write_bed(.x, .y$Bam))


### Now do for the breakpoint 2
# 1) pivot both breakpoints into one table
screenshotter_df <- Ig_caller_df_cfWGS_filtered_aggressive2 %>%
  filter(Common_MM_translocation == 1) %>% 
  select(
    Bam        = Bam_File,
    Chromosome = break2_chromosome,
    Start      = break2_position_start,
    End        = break2_position_end,
    Name       = Translocation
  ) %>%
  distinct() %>%
  mutate(
    # pull 50 bp upstream, but not below 1:
    Start = pmax(1, Start - 50),
    # push 50 bp downstream:
    End   = End   + 50
  )

# 2) load the “canonical” list of BAMs (no .bam suffix)
current_bams <- read_csv("IG_Mini_Bams.csv")$Name %>%
  str_remove("\\.bam$")

# Detect missing BAM names. As above, mapping uses the nearest inventory string
# without a maximum-distance cutoff and prints the proposed replacements.
screenshot_bams <- str_remove(screenshotter_df$Bam, "\\.bam$")
missing_bams    <- setdiff(screenshot_bams, current_bams)

# For each missing BAM, find the closest match in current_bams based on Levenshtein distance
closest_matches <- sapply(missing_bams, function(miss) {
  distances <- stringdist(miss, current_bams, method = "lv")
  current_bams[which.min(distances)]
})

# Combine results into a data frame and print
result <- data.frame(
  Missing_BAM = missing_bams,
  Closest_Match = closest_matches,
  stringsAsFactors = FALSE
)
print(result)

# Historical manually inspected names; this vector is not used downstream.
keep <- c(
  "TFRIM4_0060_Bm_P_WG_FZ-09.filter.deduped.recalibrated",
  "TFRIM4_0178_Bm_P_WG_FZ-07.filter.deduped.recalibrated",
  "TFRIM4_0184_Bm_P_WG_VA-10-01-O-DNA.filter.deduped.recalibrated",
  "TFRIM4_0187_Bm_P_WG_VA-13-01-O-DNA.filter.deduped.recalibrated"
)

# 3. apply any name fixes, then split out groups
screenshotter_df <- screenshotter_df %>%
  mutate(Bam = str_remove(Bam, "\\.bam$")) %>%
  left_join(result, by = c("Bam" = "Missing_BAM")) %>%
  mutate(Bam = coalesce(Closest_Match, Bam)) %>%
  select(-Closest_Match)

# 4. write BEDs
outdir_bed <- "IGV_screenshotter/Bed_files_translocations_cytoband_breakpoint_2"
if (!dir.exists(outdir_bed)) dir.create(outdir_bed, recursive = TRUE)

write_bed <- function(df, bam_name) {
  bed <- df %>%
    mutate(
      Chromosome = if_else(str_starts(Chromosome,"chr"), Chromosome, paste0("chr",Chromosome)),
      Start      = Start,
      End        = End
    ) %>%
    select(Chromosome, Start, End, Name)
  # write into the outdir:
  write_tsv(bed,
            file.path(outdir_bed, paste0(bam_name, ".bed")),
            col_names = FALSE)
}


screenshotter_df %>%
  group_by(Bam) %>%
  group_walk(~ write_bed(.x, .y$Bam))


add_col_if_missing <- function(df, colname, default = NA_integer_) {
  if (!colname %in% colnames(df)) {
    df[[colname]] <- default
  }
  df
}



gene_translocation_cols <- c("IGH-MAF", "IGH-CCND1", "IGH-MYC", "IGH-FGFR3")
for (col in gene_translocation_cols) {
  translocation_matrix <- add_col_if_missing(translocation_matrix, col, default = 0L)
}

translocation_feature_cols <- setdiff(
  names(translocation_matrix),
  c("Bam_File", "Patient", "Timepoint", "Sample_type", "Sample_ID", "timepoint_info")
)
translocation_matrix <- translocation_matrix %>%
  mutate(across(all_of(translocation_feature_cols), ~ replace_na(as.integer(.x), 0L)))

#  Prepare translocation data
translocation_data <- translocation_matrix %>%
  select(Bam_File, IGH_MAF = `IGH-MAF`, IGH_CCND1 = `IGH-CCND1`, IGH_MYC = `IGH-MYC`, IGH_FGFR3 = `IGH-FGFR3`) %>%
  mutate(Sample = gsub(".bam$", "", Bam_File))  # Remove '.bam' extension if present

cyto_cols <- c(
  "chr11q13.2_chr14q32.33",
  "chr11q13.3_chr14q32.33",
  "chr14q32.33_chr4p16.3",
  "chr14q32.33_chr16q23.2",
  "chr14q32.33_chr8q24.21"
)
for (col in cyto_cols) {
  translocation_matrix_cytoband <- add_col_if_missing(translocation_matrix_cytoband, col, default = 0L)
}

translocation_data_cytoband <- translocation_matrix_cytoband %>%
  # A t(11;14) call may be assigned to either adjacent 11q13 cytoband.
  # Combine the two binary indicators with OR rather than coalesce(): absent
  # calls are encoded as 0, so coalesce(0, 1) would incorrectly return 0.
  mutate(
    IGH_CCND1 = pmax(
      coalesce(.data[["chr11q13.2_chr14q32.33"]], 0L),
      coalesce(.data[["chr11q13.3_chr14q32.33"]], 0L)
    )
  ) %>%
  # now pick off and rename all four
  transmute(
    Bam_File = Bam_File,
    Sample      = gsub(".bam$", "", Bam_File),        # drop “.bam”
    IGH_CCND1,                                     
    IGH_FGFR3 = `chr14q32.33_chr4p16.3`,
    IGH_MAF   = `chr14q32.33_chr16q23.2`,
    IGH_MYC   = `chr14q32.33_chr8q24.21`
  )

## Export automated translocation feature tables
# These are useful intermediates, but the final cytoband matrix below is rebuilt
# after manual IGV confirmation using the reviewed xlsm file.
# Define export directories. Final IGV-confirmed outputs remain in
# Jan2025_exported_data because downstream scripts read them there; automated
# pre-IGV helper matrices are support-only.
export_dir <- "Jan2025_exported_data"
pre_igv_dir <- file.path(support_table_dir, "pre_igv_feature_matrices")
dir.create(export_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(pre_igv_dir, recursive = TRUE, showWarnings = FALSE)

# Exporting dataframes as RDS files
saveRDS(translocation_data, file = file.path(pre_igv_dir, "translocation_data.rds"))
saveRDS(translocation_data_cytoband, file = file.path(pre_igv_dir, "translocation_data_cytoband.rds"))

# Exporting dataframes as text files
write.table(translocation_data, file = file.path(pre_igv_dir, "translocation_data.txt"), sep = "\t", row.names = FALSE, quote = FALSE)
write.table(translocation_data_cytoband, file = file.path(pre_igv_dir, "translocation_data_cytoband.txt"), sep = "\t", row.names = FALSE, quote = FALSE)


## Export candidate calls for manual IGV checking
# The resulting text file is the input to the IGV review workbook. The final
# cytoband translocation matrix used in the manuscript is rebuilt only from calls
# marked Looks_real == 1 in the reviewed workbook.
filtered_df <- Ig_caller_df_cfWGS_filtered_aggressive2 %>%
  dplyr::filter(
    timepoint_info %in% c("Baseline", "Diagnosis"),
    Patient %in% cohort_df$Patient,
    Common_MM_translocation == 1
  )

spring2026_revision_metadata_for_igv <- load_spring2026_revision_metadata(required = FALSE)
if (!is.null(spring2026_revision_metadata_for_igv)) {
  spring2026_revision_patients_for_igv <- spring2026_revision_metadata_for_igv %>%
    filter(!is.na(.data$Patient), nzchar(.data$Patient)) %>%
    distinct(.data$Patient) %>%
    pull(.data$Patient)

  # Keep a complete review queue as well as the smaller baseline table below.
  # Nothing in this file is promoted until the manual IGV result is recorded.
  spring2026_all_igv_candidates <- Ig_caller_df_cfWGS_filtered_aggressive2 %>%
    filter(
      .data$Patient %in% spring2026_revision_patients_for_igv,
      .data$Sample_type %in% c("BM_cells", "Blood_plasma_cfDNA")
    ) %>%
    distinct(
      .data$Patient,
      .data$Sample_ID,
      .data$Bam_File,
      .data$breakpoint1,
      .data$breakpoint2,
      .keep_all = TRUE
    ) %>%
    mutate(
      review_priority = case_when(
        .data$timepoint_info %in% c("Baseline", "Diagnosis") &
          .data$Common_MM_translocation == 1 ~ "1_baseline_common_MM",
        .data$timepoint_info %in% c("Baseline", "Diagnosis") &
          .data$Other_gene %in% key_myeloma_genes ~ "2_baseline_driver_gene",
        .data$timepoint_info %in% c("Baseline", "Diagnosis") ~ "3_baseline_other",
        .data$Common_MM_translocation == 1 ~ "4_longitudinal_common_MM",
        .data$Other_gene %in% key_myeloma_genes ~ "5_longitudinal_driver_gene",
        TRUE ~ "6_longitudinal_other"
      ),
      manual_review_status = "not_reviewed",
      Looks_real = NA_real_,
      IGV_notes = NA_character_,
      final_matrix_status = "not_promoted_until_Looks_real_1_in_reviewed_xlsm"
    ) %>%
    arrange(
      .data$review_priority,
      .data$Patient,
      .data$Sample_ID,
      desc(.data$IGCaller_Score)
    )

  readr::write_csv(
    spring2026_all_igv_candidates,
    support_path("spring2026_IgCaller_all_passing_BM_cfDNA_calls_for_IGV_review.csv")
  )

  # This is the smaller set that can enter the baseline translocation matrix
  # after review.
  spring2026_igv_candidates <- filtered_df %>%
    # Match patients rather than sample IDs because the same library sometimes
    # has an older MyP/MyR name and a newer IMG name. Matching sample IDs would
    # miss those calls.
    filter(.data$Patient %in% spring2026_revision_patients_for_igv) %>%
    distinct(
      .data$Patient,
      .data$Sample_ID,
      .data$Bam_File,
      .data$breakpoint1,
      .data$breakpoint2,
      .keep_all = TRUE
    ) %>%
    mutate(
      manual_review_status = "candidate_requires_IGV_review_before_feature_matrix",
      final_matrix_status = "not_promoted_until_Looks_real_1_in_reviewed_xlsm"
    ) %>%
    arrange(.data$Patient, .data$Sample_ID, desc(.data$IGCaller_Score))
  readr::write_csv(
    spring2026_igv_candidates,
    support_path("spring2026_IgCaller_common_MM_translocation_candidates_for_IGV_review.csv")
  )
}

write.table(
