### Read and combine the IGV-reviewed call tables
# After automated filtering, each candidate common MM translocation at a
# diagnosis/baseline timepoint was manually reviewed in IGV using the mini-BAM
# files generated by the IGV_screenshotter workflow. Historical calls remain in
# the original xlsm without modification. Newly adjudicated revision calls live
# in a separate tracked TSV and are matched back to the current parsed IgCaller
# table by patient, BAM, and both exact breakpoints. This prevents the revision
# review from changing or overriding an original call.
legacy_igv_review_path <- file.path(
  export_dir,
  "Ig_caller_df_cfWGS_filtered_aggressive2_iGV_check.xlsm"
)
revision_igv_review_path <- first_existing(
  c(
    file.path(
      "Scripts_2025", "Final_Scripts", "data", "curation",
      "igcaller_revision_2026_igv_review.tsv"
    ),
    file.path("data", "curation", "igcaller_revision_2026_igv_review.tsv")
  ),
  "revision IgCaller IGV review table"
)

legacy_igv_review <- readxl::read_excel(legacy_igv_review_path)
revision_igv_review <- readr::read_tsv(
  revision_igv_review_path,
  show_col_types = FALSE,
  progress = FALSE
)

review_key <- c("Patient", "Bam_File", "breakpoint1", "breakpoint2")
required_revision_review_columns <- c(
  "call_id", review_key, "Looks_real", "review_status", "IGV_notes"
)
missing_revision_review_columns <- setdiff(
  required_revision_review_columns,
  names(revision_igv_review)
)
if (length(missing_revision_review_columns) > 0L) {
  stop(
    "Revision IgCaller IGV review table is missing required columns: ",
    paste(missing_revision_review_columns, collapse = ", "),
    call. = FALSE
  )
}
if (anyDuplicated(revision_igv_review$call_id)) {
  stop("Revision IgCaller IGV review table contains duplicate call_id values.", call. = FALSE)
}
if (anyDuplicated(revision_igv_review[review_key])) {
  stop("Revision IgCaller IGV review table contains duplicate exact call keys.", call. = FALSE)
}
allowed_review_scores <- c(0, 0.25, 0.5, 0.75, 1)
if (
  any(is.na(revision_igv_review$Looks_real)) ||
    any(!revision_igv_review$Looks_real %in% allowed_review_scores)
) {
  stop(
    "Revision Looks_real values must be one of: ",
    paste(allowed_review_scores, collapse = ", "),
    call. = FALSE
  )
}
if (any(revision_igv_review$review_status != "adjudicated")) {
  stop("All rows in the revision review table must have review_status='adjudicated'.", call. = FALSE)
}

legacy_revision_overlap <- legacy_igv_review %>%
  semi_join(revision_igv_review, by = review_key)
if (nrow(legacy_revision_overlap) > 0L) {
  stop(
    "Revision review rows overlap historical reviewed calls. The historical ",
    "workbook must remain authoritative for original calls.",
    call. = FALSE
  )
}

revision_candidate_matches <- Ig_caller_df_cfWGS_filtered_aggressive2 %>%
  semi_join(revision_igv_review, by = review_key)
if (nrow(revision_candidate_matches) != nrow(revision_igv_review)) {
  unmatched_revision_calls <- revision_igv_review %>%
    anti_join(Ig_caller_df_cfWGS_filtered_aggressive2, by = review_key) %>%
    pull(.data$call_id)
  stop(
    "Expected one current IgCaller candidate for every revision review row. ",
    "Matched ", nrow(revision_candidate_matches), " of ",
    nrow(revision_igv_review), ". Unmatched call_id values: ",
    paste(unmatched_revision_calls, collapse = ", "),
    call. = FALSE
  )
}

revision_reviewed_calls <- revision_candidate_matches %>%
  inner_join(
    revision_igv_review %>%
      select(
        all_of(review_key),
        call_id,
        reviewed_Looks_real = Looks_real,
        review_confidence,
        review_status,
        reviewed_IGV_notes = IGV_notes
      ),
    by = review_key
  ) %>%
  mutate(
    Looks_real = .data$reviewed_Looks_real,
    Notes = .data$reviewed_IGV_notes,
    review_source = "revision_2026_tsv"
  )

review_matrix_columns <- c(
  "Bam_File", "Patient", "Timepoint", "Sample_type", "Sample_ID",
  "timepoint_info", "Sorted_translocation", "IGCaller_Score",
  "Common_MM_translocation", "Looks_real", "Notes"
)
missing_legacy_matrix_columns <- setdiff(
  review_matrix_columns,
  names(legacy_igv_review)
)
missing_revision_matrix_columns <- setdiff(
  review_matrix_columns,
  names(revision_reviewed_calls)
)
if (length(missing_legacy_matrix_columns) > 0L) {
  stop(
    "Historical IGV workbook is missing matrix columns: ",
    paste(missing_legacy_matrix_columns, collapse = ", "),
    call. = FALSE
  )
}
if (length(missing_revision_matrix_columns) > 0L) {
  stop(
    "Matched revision calls are missing matrix columns: ",
    paste(missing_revision_matrix_columns, collapse = ", "),
    call. = FALSE
  )
}

legacy_reviewed_calls <- legacy_igv_review %>%
  select(all_of(review_matrix_columns)) %>%
  mutate(review_source = "historical_xlsm")
revision_reviewed_calls_for_matrix <- revision_reviewed_calls %>%
  select(all_of(review_matrix_columns)) %>%
  mutate(review_source = "revision_2026_tsv")

iGV_reviewed_all <- bind_rows(
  legacy_reviewed_calls,
  revision_reviewed_calls_for_matrix
)
iGV_verified <- iGV_reviewed_all %>%
  filter(.data$Looks_real == 1)

revision_review_audit <- revision_reviewed_calls %>%
  transmute(
    .data$call_id,
    .data$Patient,
    .data$Sample_ID,
    .data$Bam_File,
    .data$breakpoint1,
    .data$breakpoint2,
    .data$Sorted_translocation,
    .data$IGCaller_Score,
    .data$Looks_real,
    .data$review_confidence,
    .data$review_status,
    IGV_notes = .data$Notes,
    final_matrix_status = if_else(
      .data$Looks_real == 1,
      "promoted_to_strict_matrix",
      "not_promoted_fractional_review_score"
    )
  ) %>%
  arrange(.data$Patient, .data$Sample_ID, desc(.data$IGCaller_Score))
readr::write_csv(
  revision_review_audit,
  support_path("revision_2026_IgCaller_IGV_review_application_audit.csv")
)
message(
  "Historical IGV calls retained unchanged: ", nrow(legacy_igv_review),
  "; revision calls appended: ", nrow(revision_reviewed_calls),
  "; revision strict calls promoted: ",
  sum(revision_reviewed_calls$Looks_real == 1)
)

## Filter to what checked 
translocation_matrix_cytoband <- iGV_verified %>%
  filter(Common_MM_translocation == 1) %>%  # Filter rows with common MM translocations
  group_by(Bam_File) %>%  # Group by Bam_File to handle duplicates
  slice_max(order_by = IGCaller_Score, n = 1, with_ties = FALSE) %>%  # Keep only the row with the highest score
  ungroup() %>%
  dplyr::select(Bam_File, Patient, Timepoint, Sample_type, Sample_ID, timepoint_info, Sorted_translocation) %>%  # Select relevant columns
  distinct() %>%  # Remove duplicates
  # Collapse specific IGH subtypes into general "IGH" in the Sorted_translocation column
  mutate(Sorted_translocation = ifelse(grepl("^IGH", Sorted_translocation), sub("_.*", "", Sorted_translocation), Sorted_translocation)) %>%
  pivot_wider(
    names_from = Sorted_translocation,  # Create columns for each translocation type
    values_from = Sorted_translocation,  # Use the same column to create 1/0
    values_fn = list(Sorted_translocation = ~1),  # Set to 1 where translocation exists
    values_fill = 0  # Fill with 0 where translocation doesn't exist
  )


# Add all needed columns if missing
for (col in cyto_cols) {
  translocation_matrix_cytoband <- add_col_if_missing(translocation_matrix_cytoband, col, default = 0L)
}


translocation_data_cytoband <- translocation_matrix_cytoband %>%
  # Treat either adjacent 11q13 cytoband as evidence of t(11;14). Explicitly
  # replace missing values with 0 before applying the binary OR via pmax().
  mutate(
    IGH_CCND1 = pmax(
      coalesce(.data[["chr11q13.2_chr14q32.33"]], 0L),
      coalesce(.data[["chr11q13.3_chr14q32.33"]], 0L)
    )
  ) %>%
  # now pick off and rename all four
  transmute(
    Bam_File = Bam_File,
    Sample      = gsub(".bam$", "", Bam_File),        # drop “.bam”
    IGH_CCND1,                                     
    IGH_FGFR3 = `chr14q32.33_chr4p16.3`,
    IGH_MAF   = `chr14q32.33_chr16q23.2`,
    IGH_MYC   = `chr14q32.33_chr8q24.21`
  )


## Final export consumed by downstream feature integration
# This is the translocation feature object used in the manuscript because it
# incorporates the manual IGV `Looks_real == 1` confirmation step.
saveRDS(translocation_data_cytoband, file = file.path(export_dir, "translocation_data_cytoband_updated.rds"))

# Exporting dataframes as text files
write.table(translocation_data_cytoband, file = file.path(export_dir, "translocation_data_cytoband_updated.txt"), sep = "\t", row.names = FALSE, quote = FALSE)
